/* 二分查找；找不到返回 NULL，上层画占位框。 */
const unsigned long long* CjkRows(unsigned int cp, int scale) {
    int lo = 0, hi = CJK_GLYPH_COUNT - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (kCjkIndex[mid].cp == cp) {
            int i = kCjkIndex[mid].glyph;
            switch (scale) {
                case 1: return &kCjkRows1[i * 12];
                case 2: return &kCjkRows2[i * 24];
                case 3: return &kCjkRows3[i * 36];
                case 4: return &kCjkRows4[i * 48];
                default: return NULL;
            }
        }
        if (kCjkIndex[mid].cp < cp) lo = mid + 1;
        else hi = mid - 1;
    }
    return NULL;
}
